CREATE OR REPLACE FUNCTION public.skillswap_compare_swap(expected bigint, replacement jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE changed boolean; BEGIN UPDATE public.skillswap_state SET data=replacement, revision=revision+1 WHERE id=true AND revision=expected; changed := FOUND; IF changed THEN UPDATE public.profiles p SET name = j.value->>'name', tagline = j.value->>'tagline', teaches=j.value->'teaches', learns=j.value->'learns', availability=j.value->'availability' FROM jsonb_each(replacement->'profiles') j WHERE p.id::text=j.key; END IF; RETURN changed; END $$;
REVOKE ALL ON FUNCTION public.skillswap_compare_swap(bigint,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.skillswap_compare_swap(bigint,jsonb) TO service_role;